// @generated by:gauntlet run:godseye-e06-completion
import { randomUUID } from "node:crypto";
import { InfrastructureEngine } from "@godseye/core";
import { afterEach, describe, expect, it } from "vitest";
import { type JobsFixture, jobsFixture } from "./jobs-helpers.js";

describe("actual Inngest cron fire identities", () => {
  let fixture: JobsFixture | undefined;
  afterEach(async () => {
    await fixture?.store.close();
    fixture = undefined;
  });
  async function setup() {
    const active = await jobsFixture();
    fixture = active;
    const definition = await active.register({ trigger: { kind: "cron", cron: "* * * * *" } });
    const engine = new InfrastructureEngine(active.store, {
      ...active.configuration,
      jobs: {
        handlers: new Map([["fixture.work", active.handler]]),
        inngestEnvironmentIds: new Set([active.development.id]),
      },
    });
    const authority = {
      projectId: active.project.id,
      environmentId: active.development.id,
      producerId: randomUUID(),
    };
    return { active, engine, definition, authority };
  }

  it("T-E06-D05 accepts the pinned server's RFC3339 cron identity and deduplicates its exact replay", async () => {
    const { active, engine, definition, authority } = await setup();
    const identity = "2026-11-12T21:00:00Z";
    const first = await engine.jobs.triggerInngestCron(
      authority,
      definition.id,
      definition.hash,
      identity,
    );
    const replay = await engine.jobs.triggerInngestCron(
      authority,
      definition.id,
      definition.hash,
      identity,
    );

    expect(replay.id).toBe(first.id);
    expect(first).toMatchObject({
      trigger: "cron",
      state: "queued",
      dedupeKey: `inngest:${identity}`,
    });
    expect((await active.jobs().overview(active.freshOwner())).runs).toHaveLength(1);
  });

  it("T-E06-D05 malformed or oversized cron identities cannot admit a run", async () => {
    const { active, engine, definition, authority } = await setup();
    for (const identity of [
      "",
      "bad:cron:id",
      "2026-11-12T99:99:99Z",
      "x".repeat(121),
      "2026-11-12T21:00:00Z\nowner-command",
    ])
      await expect(
        Promise.resolve().then(() =>
          engine.jobs.triggerInngestCron(authority, definition.id, definition.hash, identity),
        ),
      ).rejects.toMatchObject({ code: "INVALID_INPUT" });

    expect((await active.jobs().overview(active.freshOwner())).runs).toHaveLength(0);
  });
});
